create table if not exists public.business_category_templates (
  id text primary key,
  group_id text not null,
  group_label text not null,
  category_label text not null,
  sort_order integer not null default 0,
  is_active boolean not null default true,
  configuration jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table public.business_category_templates enable row level security;
revoke all on table public.business_category_templates from anon;
grant select, insert, update, delete on table public.business_category_templates to authenticated;

drop policy if exists business_category_templates_platform_admin on public.business_category_templates;
create policy business_category_templates_platform_admin
on public.business_category_templates
for all
to authenticated
using (private.is_platform_admin())
with check (private.is_platform_admin());

